#include "piper_workbench/main_window.hpp"
#include "piper_workbench/backend_client.hpp"
using namespace Ui;
QWidget *MainWindow::makeCapture(){
 auto *page=new QWidget;page->setObjectName("page");auto *layout=new QVBoxLayout(page);layout->setContentsMargins(20,20,20,16);layout->setSpacing(12);layout->addWidget(text("图片采集","pageTitle"));layout->addWidget(text("采集原始彩色图片，导出后用于 YOLO 标注与训练"));
 auto *selection=card("");auto *select=new QHBoxLayout;select->addWidget(text("相机选择"));captureD455_=new QCheckBox("D455 固定相机");captureDabai_=new QCheckBox("Dabai 腕载相机");captureD455_->setChecked(true);captureDabai_->setChecked(true);select->addWidget(captureD455_);select->addWidget(captureDabai_);select->addStretch();select->addWidget(text("保存目录  data/datasets · 两路独立时间戳"));auto *open=button("打开采集目录",false,"logs");select->addWidget(open);connect(open,&QPushButton::clicked,this,[this]{showFile(QString::fromLocal8Bit(qgetenv("AGX_ARM_WS"))+"/data/datasets");});static_cast<QVBoxLayout *>(selection->layout())->addLayout(select);layout->addWidget(selection);
 auto *row=new QHBoxLayout;row->setSpacing(12);layout->addLayout(row,3);
 for(QString cam:{"d455","dabai"}){auto *box=card(cam=="d455"?"D455 · 640 × 480":"Dabai · 640 × 480");auto *bl=static_cast<QVBoxLayout *>(box->layout());auto *view=new ImageView;images_[cam+":raw"]=view;bl->addWidget(view,1);row->addWidget(box,2);}
 auto *settings=card("采集控制");auto *sl=static_cast<QVBoxLayout *>(settings->layout());auto cameras=[this]{QJsonArray cams;if(captureD455_->isChecked())cams.append("d455");if(captureDabai_->isChecked())cams.append("dabai");return cams;};
 auto *single=button("拍摄一张",true,"capture");captureOnceButton_=single;sl->addWidget(single);connect(single,&QPushButton::clicked,this,[this,cameras,single]{request(single,"capture.once",{{"cameras",cameras()}},[this](QJsonValue v){applyCaptureResult(v.toObject(),false);},"正在拍摄…",{});});sl->addSpacing(6);auto *line=new QFrame;line->setFrameShape(QFrame::HLine);line->setStyleSheet("color:#E2E8F0");sl->addWidget(line);sl->addWidget(text("定时采集","cardTitle"));
 auto *form=new QFormLayout;captureInterval_=new QDoubleSpinBox;captureInterval_->setRange(.1,3600);captureInterval_->setValue(2);captureInterval_->setSuffix(" 秒");form->addRow("采集间隔",captureInterval_);sl->addLayout(form);auto *bar=new QHBoxLayout;auto *start=button("开始采集",true,"play"),*stop=button("停止",false,"stop");captureStartButton_=start;captureStopButton_=stop;bar->addWidget(start,2);bar->addWidget(stop,1);sl->addLayout(bar);connect(start,&QPushButton::clicked,this,[this,cameras,start]{request(start,"capture.start",{{"cameras",cameras()},{"interval",captureInterval_->value()}},[this](QJsonValue){captureRunning_=true;updateCaptureButtons();captureState_->setText("定时采集运行中 · 等待新图像");},"正在开始…",{},true);});connect(stop,&QPushButton::clicked,this,[this,stop]{request(stop,"capture.stop",{},[this](QJsonValue){captureRunning_=false;updateCaptureButtons();captureState_->setText("采集已停止 · 后续图像不再追加");},"正在停止…",{},true);});
 captureState_=text("尚未采集","notice");sl->addWidget(captureState_);sl->addStretch();row->addWidget(settings,1);
 auto *recent=card("最近采集 · 原始 PNG");captureImages_=new QListWidget;captureImages_->setViewMode(QListView::IconMode);captureImages_->setIconSize(QSize(130,90));captureImages_->setGridSize(QSize(170,126));captureImages_->setResizeMode(QListView::Adjust);captureImages_->setFlow(QListView::LeftToRight);captureImages_->setWordWrap(true);static_cast<QVBoxLayout *>(recent->layout())->addWidget(captureImages_,1);layout->addWidget(recent,1);
 auto *footer=card("");auto *fl=new QHBoxLayout;fl->addWidget(text("默认导出原图，不含检测框；双路采集必须同时取得两路新画面，缺任一路时整次不保存。两路时间戳独立，不宣称硬件同步曝光。"),1);auto *exportButton=button("导出图片会话 ZIP",true,"save");fl->addWidget(exportButton);static_cast<QVBoxLayout *>(footer->layout())->addLayout(fl);layout->addWidget(footer);
 connect(exportButton,&QPushButton::clicked,this,[this,exportButton]{request(exportButton,"capture.export",{},[this](QJsonValue v){lastExport_=v.toObject()["path"].toString();toast_->setText("原图已导出："+lastExport_);auto dest=QFileDialog::getSaveFileName(this,"另存为图片会话 ZIP",lastExport_,"ZIP (*.zip)");if(dest.isEmpty()||dest==lastExport_)return;QFile source(lastExport_);QSaveFile out(dest);if(!source.open(QFile::ReadOnly)||!out.open(QFile::WriteOnly)){showError("导出目标无法写入");return;}while(!source.atEnd())out.write(source.read(1024*1024));if(!out.commit())showError("ZIP 导出写入失败");},"正在导出…","导出成功");});updateCaptureButtons();return page;
}
